with exploded as (select id, service, latency_ms, status_code, key, attr_value from app_logs lateral view outer explode(context) e as key, attr_value) select *, percent_rank() over w_ordered status_code_percent_rank, corr(latency_ms, status_code) over w_running corr_latency_ms_status_code from exploded where service = 'auth' window w_ordered as (partition by key order by status_code), w_running as (partition by key)
